import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  DeleteRecords Request (Version: 1) => [topics] timeout_ms
    topics => name [partitions]
      name => STRING
      partitions => partition_index offset
        partition_index => INT32
        offset => INT64
    timeout_ms => INT32
*/
export function createRequest(topics, timeoutMs) {
    return Writer.create()
        .appendArray(topics, (writer, topic) => writer
        .appendString(topic.name, false)
        .appendArray(topic.partitions, (writer, partition) => writer.appendInt32(partition.partitionIndex).appendInt64(partition.offset), false, false), false, false)
        .appendInt32(timeoutMs);
}
/*
  DeleteRecords Response (Version: 1) => throttle_time_ms [topics]
    throttle_time_ms => INT32
    topics => name [partitions]
      name => STRING
      partitions => partition_index low_watermark error_code
        partition_index => INT32
        low_watermark => INT64
        error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        topics: reader.readArray((r, topicIndex) => ({
            name: r.readString(false),
            partitions: r.readArray((r, partitionIndex) => {
                const partition = { partitionIndex: r.readInt32(), lowWatermark: r.readInt64(), errorCode: r.readInt16() };
                if (partition.errorCode !== 0) {
                    errors.push([`topics[${topicIndex}].partitions[${partitionIndex}]`, [partition.errorCode, null]]);
                }
                return partition;
            }, false, false)
        }), false, false)
    };
    if (errors.length) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(21, 1, createRequest, parseResponse, false, false);
